import random

def count_pairs(adj, n):
    pairs = 0
    for i in range(n):
        for j in range(i + 1, n):
            if adj[i][j] == 0:
                # Check for common neighbor
                has_common = False
                for k in range(n):
                    if adj[i][k] == 1 and adj[j][k] == 1:
                        has_common = True
                        break
                if has_common:
                    pairs += 1
    return pairs

def random_graph(n, p):
    adj = [[0]*n for _ in range(n)]
    for i in range(n):
        for j in range(i+1, n):
            if random.random() < p:
                adj[i][j] = adj[j][i] = 1
    return adj

def test_star(n):
    adj = [[0]*n for _ in range(n)]
    for i in range(1, n):
        adj[0][i] = adj[i][0] = 1
    return count_pairs(adj, n)

def test_complete_bipartite(n, a):
    b = n - a
    adj = [[0]*n for _ in range(n)]
    for i in range(a):
        for j in range(a, n):
            adj[i][j] = adj[j][i] = 1
    return count_pairs(adj, n)

def test_cycle(n):
    adj = [[0]*n for _ in range(n)]
    for i in range(n):
        j = (i + 1) % n
        adj[i][j] = adj[j][i] = 1
    return count_pairs(adj, n)

